import{_ as t,o as a,c as s,a2 as d}from"./chunks/framework.BZO4qERu.js";const C=JSON.parse('{"title":"Claude Code","description":"通过 CC Switch 为 Claude Code 配置 Tokeness API Key、Base URL、模型名和路由模式。","frontmatter":{"title":"Claude Code","description":"通过 CC Switch 为 Claude Code 配置 Tokeness API Key、Base URL、模型名和路由模式。"},"headers":[],"relativePath":"zh/integrations/claude-code.md","filePath":"zh/integrations/claude-code.md","lastUpdated":1783490293000}'),i={name:"zh/integrations/claude-code.md"};function o(l,e,n,h,c,p){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>Claude Code 原生使用 Anthropic 协议。Tokeness 的通用接口是 OpenAI 兼容协议，所以用 Claude Code 接入 Tokeness 时，通过 <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a> 管理供应商，并开启路由模式。</p><p>这一页按“新机器从零接入”的流程写。如果你已经装好 Claude Code 和 CC Switch，可以直接从“添加 Tokeness 供应商”开始。</p><h2 id="接入信息" tabindex="-1">接入信息 <a class="header-anchor" href="#接入信息" aria-label="Permalink to &quot;接入信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Provider Name</td><td><code>Tokeness</code></td></tr><tr><td>API Format</td><td><code>OpenAI Compatible</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model</td><td>从 Tokeness 模型广场复制</td></tr></tbody></table><p>Claude Code 直接走 OpenAI 兼容接口时，必须确认 CC Switch 已经接管并完成协议转换。没有路由转换时，Claude Code 可能把 Anthropic Messages 请求发到 OpenAI 兼容接口，导致 400、404 或工具调用异常。</p><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先在 Tokeness 控制台完成：</p><ol><li>进入钱包，确认余额可用。</li><li>进入 API 密钥页面，创建一个 Claude Code 专用 Key。</li><li>进入模型广场，复制一个适合编码任务的模型名。</li><li>打开使用日志页面，后面验证请求是否进入 Tokeness。</li></ol><p>Key 名称可以写成：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude-code-local</span></span></code></pre></div><p>不要把 Key 写进项目仓库，也不要截图完整 Key。</p><h2 id="_2-安装-claude-code" tabindex="-1">2. 安装 Claude Code <a class="header-anchor" href="#_2-安装-claude-code" aria-label="Permalink to &quot;2. 安装 Claude Code&quot;">​</a></h2><p>确认本机有 Node.js：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>安装 Claude Code：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><p>如果 npm 下载较慢：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry=https://registry.npmmirror.com</span></span></code></pre></div><p>确认命令可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>如果系统提示找不到 <code>claude</code>，关闭当前终端并重新打开，再执行一次。</p><h2 id="_3-安装-cc-switch" tabindex="-1">3. 安装 CC Switch <a class="header-anchor" href="#_3-安装-cc-switch" aria-label="Permalink to &quot;3. 安装 CC Switch&quot;">​</a></h2><p>打开 CC Switch 文档并安装：</p><p><a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">https://ccswitch.io/zh/docs?section=getting-started</a></p><p>安装完成后启动 CC Switch。Windows 和 macOS 通常会在系统托盘或菜单栏看到图标。</p><p>如果 CC Switch 提示找不到 Claude Code，先确认 <code>claude --version</code> 在普通终端里可用。</p><h2 id="_4-添加-tokeness-供应商" tabindex="-1">4. 添加 Tokeness 供应商 <a class="header-anchor" href="#_4-添加-tokeness-供应商" aria-label="Permalink to &quot;4. 添加 Tokeness 供应商&quot;">​</a></h2><ol><li>打开 CC Switch。</li><li>左侧选择 <code>Claude Code</code>。</li><li>点击右上角 <code>+</code> 添加供应商。</li><li>如果预设里没有 Tokeness，选择自定义供应商。</li><li>名称填写 <code>Tokeness</code>。</li><li>API 格式选择 <code>OpenAI Compatible</code> 或 <code>OpenAI</code>。</li><li>API Key 填写 Tokeness API Key。</li><li>Base URL 填写 <code>https://n.tokeness.io/v1</code>。</li><li>模型填写 Tokeness 模型广场里的完整模型名。</li><li>保存。</li></ol><p>如果界面提供“获取模型列表”，可以试一次。拉取失败时，手动填写模型名即可。</p><h2 id="_5-开启路由模式" tabindex="-1">5. 开启路由模式 <a class="header-anchor" href="#_5-开启路由模式" aria-label="Permalink to &quot;5. 开启路由模式&quot;">​</a></h2><p>Claude Code 需要重点检查这一项。</p><p>在 CC Switch 的 Claude Code 设置里，找到路由、代理或本地转发相关开关，并开启。不同版本的 CC Switch 文案可能略有差异，含义是让 Claude Code 请求先进入 CC Switch，再由 CC Switch 转发到自定义供应商。</p><p>开启后，CC Switch 会把 Claude Code 的请求转换成目标供应商能接收的格式。Tokeness 这里选择 OpenAI 兼容格式。</p><p>如果没有开启路由模式，常见表现是：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>Claude Code 启动正常但请求失败</td><td>请求格式没有转换</td></tr><tr><td>Tokeness 没有使用日志</td><td>请求没有发到 Tokeness</td></tr><tr><td>返回 404</td><td>请求路径不是 OpenAI 兼容路径</td></tr><tr><td>工具调用失败</td><td>Anthropic 与 OpenAI 工具调用格式没有转换</td></tr></tbody></table><h2 id="_6-启用并重启-claude-code" tabindex="-1">6. 启用并重启 Claude Code <a class="header-anchor" href="#_6-启用并重启-claude-code" aria-label="Permalink to &quot;6. 启用并重启 Claude Code&quot;">​</a></h2><p>在 CC Switch 中启用 Tokeness 供应商。然后关闭当前 Claude Code 进程，重新打开终端。</p><p>运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>如果是第一次运行 Claude Code，可能会出现官方初始化引导。按 CC Switch 文档完成初始化；如果 CC Switch 提供“跳过首次确认”选项，也可以开启后再重启。</p><h2 id="_7-验证" tabindex="-1">7. 验证 <a class="header-anchor" href="#_7-验证" aria-label="Permalink to &quot;7. 验证&quot;">​</a></h2><p>在 Claude Code 里输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好。请只回复一句话，说明你已经可以工作。</span></span></code></pre></div><p>成功后检查 Tokeness：</p><ol><li>打开使用日志。</li><li>找到刚才的请求。</li><li>确认 Key、模型名、状态码和消耗正常。</li></ol><p>如果 Claude Code 有回复，但日志里没有记录，说明当前请求没有走 Tokeness。</p><h2 id="_8-常用切换方式" tabindex="-1">8. 常用切换方式 <a class="header-anchor" href="#_8-常用切换方式" aria-label="Permalink to &quot;8. 常用切换方式&quot;">​</a></h2><p>如果你有多个 Tokeness Key 或多个模型，可以在 CC Switch 里建多个供应商：</p><table tabindex="0"><thead><tr><th>名称</th><th>用途</th></tr></thead><tbody><tr><td><code>Tokeness Coding</code></td><td>日常编码</td></tr><tr><td><code>Tokeness Reasoning</code></td><td>复杂推理</td></tr><tr><td><code>Tokeness Low Cost</code></td><td>批量改文档、简单任务</td></tr></tbody></table><p>切换供应商后，重新打开终端再运行 <code>claude</code>，避免旧进程继续使用旧配置。</p><h2 id="_9-排查" tabindex="-1">9. 排查 <a class="header-anchor" href="#_9-排查" aria-label="Permalink to &quot;9. 排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td><code>claude</code> 命令不存在</td><td>重新安装 Claude Code，或重启终端</td></tr><tr><td>CC Switch 找不到 Claude Code</td><td>确认 <code>claude --version</code> 可用</td></tr><tr><td>401 Unauthorized</td><td>重新复制 Tokeness API Key</td></tr><tr><td>404 Not Found</td><td>Base URL 填 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>model not found</td><td>从模型广场重新复制模型名</td></tr><tr><td>Tokeness 无日志</td><td>确认 Tokeness 供应商已启用，并开启 CC Switch 路由模式</td></tr><tr><td>回复很慢</td><td>换模型，或检查当前模型负载和网络</td></tr><tr><td>工具调用报错</td><td>确认走 CC Switch 路由；复杂工具调用需要协议转换完整</td></tr></tbody></table>`,53)])])}const k=t(i,[["render",o]]);export{C as __pageData,k as default};
